          fix: { kind: "add-field", title: "\u0414\u043E\u0431\u0430\u0432\u0438\u0442\u044C \u041A\u0430\u043D\u0430\u043B:", snippet: '\u041A\u0430\u043D\u0430\u043B: "\u043D\u0430\u0437\u0432\u0430\u043D\u0438\u0435 \u043A\u0430\u043D\u0430\u043B\u0430"' }
