var SVC_KEYWORD_DOCS = {
  "\u0423\u0441\u043B\u0443\u0433\u0430:": "\u0423\u0441\u043B\u0443\u0433\u0430 \u2014 \u043A\u043E\u0440\u0435\u043D\u044C svcflow. \u0427\u0442\u043E \u043C\u044B \u043F\u0440\u043E\u0434\u0430\u0451\u043C: \u043E\u0431\u0435\u0449\u0430\u043D\u0438\u044F, \u0441\u0435\u0433\u043C\u0435\u043D\u0442\u044B, \u043F\u0435\u0440\u0441\u043E\u043D\u044B, \u043A\u043E\u043D\u0442\u0435\u043A\u0441\u0442\u044B, \u043E\u043F\u043E\u0440\u044B.",
  "\u041E\u0431\u0435\u0449\u0430\u043D\u0438\u0435:": "\u041E\u0431\u0435\u0449\u0430\u043D\u0438\u0435 \u2014 \u0447\u0442\u043E \u043A\u043B\u0438\u0435\u043D\u0442 \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 \u043D\u0430 \u0440\u0443\u043A\u0438. \u0418\u043C\u0435\u0435\u0442 \u0424\u043E\u0440\u043C\u0443\u043B\u0438\u0440\u043E\u0432\u043A\u0443 \u0438 \u0441\u043F\u0438\u0441\u043E\u043A \u041A\u043E\u043C\u0443.",
  "\u041F\u0435\u0440\u0441\u043E\u043D\u0430:": "\u041F\u0435\u0440\u0441\u043E\u043D\u0430 \u2014 \u0442\u0438\u043F\u0430\u0436 \u043A\u043B\u0438\u0435\u043D\u0442\u0430 \u0432 \u0440\u0430\u043C\u043A\u0430\u0445 \u0441\u0435\u0440\u0432\u0438\u0441\u0430 (\u0421\u0435\u0433\u043C\u0435\u043D\u0442 + \u041E\u043F\u0438\u0441\u0430\u043D\u0438\u0435).",
  "\u041A\u043E\u043D\u0442\u0435\u043A\u0441\u0442:": "\u041A\u043E\u043D\u0442\u0435\u043A\u0441\u0442 \u2014 \u0441\u0438\u0442\u0443\u0430\u0446\u0438\u044F \u043E\u0431\u0440\u0430\u0449\u0435\u043D\u0438\u044F. \u0412\u043A\u043B\u044E\u0447\u0430\u0435\u0442 \u0427\u0442\u043E_\u0432\u0430\u0436\u043D\u043E/\u0427\u0442\u043E_\u043D\u0435_\u0432\u0430\u0436\u043D\u043E \u0438 \u041E\u0431\u0435\u0449\u0430\u043D\u0438\u044F \u0441 \u0443\u0440\u043E\u0432\u043D\u044F\u043C\u0438.",
  "\u0421\u0446\u0435\u043D\u0430\u0440\u0438\u0439:": "\u0421\u0446\u0435\u043D\u0430\u0440\u0438\u0439 \u2014 \u043F\u0440\u043E\u0437\u0440\u0430\u0447\u043D\u0430\u044F \u043C\u0435\u0445\u0430\u043D\u0438\u043A\u0430: \u0423\u0441\u043B\u0443\u0433\u0430 \xD7 \u041F\u0435\u0440\u0441\u043E\u043D\u0430 \xD7 \u041A\u043E\u043D\u0442\u0435\u043A\u0441\u0442. \u0414\u0430\u043D\u043E/\u041A\u043E\u0433\u0434\u0430/\u0422\u043E\u0433\u0434\u0430 + \u041F\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u0435\u0442.",
  "\u041E\u043F\u043E\u0440\u0430:": "\u041E\u043F\u043E\u0440\u0430 \u2014 \u0430\u043A\u0442\u0438\u0432 \u0438\u043B\u0438 \u043F\u0440\u043E\u0446\u0435\u0441\u0441, \u043D\u0430 \u043A\u043E\u0442\u043E\u0440\u043E\u043C \u0434\u0435\u0440\u0436\u0438\u0442\u0441\u044F \u043E\u0431\u0435\u0449\u0430\u043D\u0438\u0435.",
  "\u0421\u0442\u0430\u0442\u0443\u0441:": "\u0421\u0442\u0430\u0442\u0443\u0441: \u0447\u0435\u0440\u043D\u043E\u0432\u0438\u043A | \u0433\u043E\u0442\u043E\u0432 (\u0441\u0446\u0435\u043D\u0430\u0440\u0438\u0439); \u0438\u0434\u0435\u044F | MVP | \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u044E\u0449\u0430\u044F (\u0443\u0441\u043B\u0443\u0433\u0430).",
  "\u0421\u043E\u0441\u0442\u043E\u044F\u043D\u0438\u0435:": "\u0421\u043E\u0441\u0442\u043E\u044F\u043D\u0438\u0435 \u043E\u043F\u043E\u0440\u044B: \u0435\u0441\u0442\u044C | \u0432_\u0440\u0430\u0431\u043E\u0442\u0435 | \u043D\u0435\u0442.",
  "\u0422\u0438\u043F:": "\u0422\u0438\u043F \u043E\u043F\u043E\u0440\u044B: \u0430\u043A\u0442\u0438\u0432 | \u043F\u0440\u043E\u0446\u0435\u0441\u0441 | \u043C\u0435\u0442\u043E\u0434\u043E\u043B\u043E\u0433\u0438\u044F | \u0441\u043E\u0446\u0438\u0430\u043B\u044C\u043D\u0430\u044F.",
  "\u041A\u0430\u0442\u0435\u0433\u043E\u0440\u0438\u044F:": "\u041A\u0430\u0442\u0435\u0433\u043E\u0440\u0438\u044F \u043E\u043F\u043E\u0440\u044B: \u043C\u0435\u0442\u043E\u0434\u043E\u043B\u043E\u0433\u0438\u0447\u0435\u0441\u043A\u0430\u044F | \u0442\u0435\u0445\u043D\u0438\u0447\u0435\u0441\u043A\u0430\u044F | \u043E\u043F\u0435\u0440\u0430\u0446\u0438\u043E\u043D\u043D\u0430\u044F | \u0441\u043E\u0446\u0438\u0430\u043B\u044C\u043D\u0430\u044F. \u041E\u043F\u0446\u0438\u043E\u043D\u0430\u043B\u044C\u043D\u043E \u2014 \u0432\u044B\u0432\u043E\u0434\u0438\u0442\u0441\u044F \u0438\u0437 \u0422\u0438\u043F:, \u043C\u043E\u0436\u0435\u0442 \u0431\u044B\u0442\u044C \u043F\u0435\u0440\u0435\u043E\u043F\u0440\u0435\u0434\u0435\u043B\u0435\u043D\u0430.",
  "\u0420\u0435\u0430\u043B\u0438\u0437\u0443\u0435\u0442:": "\u0421\u0441\u044B\u043B\u043A\u0430 \u043D\u0430 \u041F\u0440\u0435\u0434\u043B\u043E\u0436\u0435\u043D\u0438\u044F \u0438\u0437 pflow, \u043A\u043E\u0442\u043E\u0440\u044B\u0435 \u0440\u0435\u0430\u043B\u0438\u0437\u0443\u0435\u0442 \u044D\u0442\u0430 \u0443\u0441\u043B\u0443\u0433\u0430.",
  "\u041E\u0431\u0435\u0441\u043F\u0435\u0447\u0438\u0432\u0430\u0435\u0442:": "\u0421\u0441\u044B\u043B\u043A\u0430 \u043D\u0430 \u0420\u0435\u0441\u0443\u0440\u0441\u044B pflow, \u043D\u0430 \u043A\u043E\u0442\u043E\u0440\u044B\u0445 \u0434\u0435\u0440\u0436\u0438\u0442\u0441\u044F \u044D\u0442\u0430 \u041E\u043F\u043E\u0440\u0430. Cross-layer reverse-index: \u0432 hover \u0420\u0435\u0441\u0443\u0440\u0441\u0430 \u043F\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u044E\u0442\u0441\u044F \u043E\u0431\u0435\u0441\u043F\u0435\u0447\u0438\u0432\u0430\u044E\u0449\u0438\u0435 \u041E\u043F\u043E\u0440\u044B.",
  "\u041B\u0438\u043D\u0435\u0439\u043A\u0430:": "\u0421\u0435\u043C\u0435\u0439\u0441\u0442\u0432\u043E \u0443\u0441\u043B\u0443\u0433 \u0441 \u0440\u0430\u0437\u043D\u044B\u043C\u0438 \u0443\u0440\u043E\u0432\u043D\u044F\u043C\u0438 \u0437\u0440\u0435\u043B\u043E\u0441\u0442\u0438. \u0418\u0434\u0451\u0442 \u0432 \u043F\u0430\u0440\u0435 \u0441 \u0423\u0440\u043E\u0432\u0435\u043D\u044C: \u043F\u0440\u0438 \u0422\u0438\u043F: \u0443\u0440\u043E\u0432\u0435\u043D\u044C.",
  "\u0423\u0440\u043E\u0432\u0435\u043D\u044C:": "\u041F\u043E\u0437\u0438\u0446\u0438\u044F \u0443\u0441\u043B\u0443\u0433\u0438 \u0432 \u043B\u0438\u043D\u0435\u0439\u043A\u0435 (1 \u2014 \u0431\u0430\u0437\u043E\u0432\u0430\u044F). \u0412 \u043E\u0434\u043D\u043E\u0439 \u043B\u0438\u043D\u0435\u0439\u043A\u0435 \u0443\u0440\u043E\u0432\u043D\u0438 \u043D\u0435 \u043F\u043E\u0432\u0442\u043E\u0440\u044F\u044E\u0442\u0441\u044F.",
  "\u041A_\u0443\u0441\u043B\u0443\u0433\u0435:": "\u041C\u0430\u0441\u0441\u0438\u0432 \u0443\u0441\u043B\u0443\u0433, \u043A \u043A\u043E\u0442\u043E\u0440\u044B\u043C \u043F\u0440\u0438\u0446\u0435\u043F\u043B\u044F\u0435\u0442\u0441\u044F \u043E\u043F\u0446\u0438\u044F. \u0417\u0430\u043F\u043E\u043B\u043D\u044F\u0435\u0442\u0441\u044F \u0442\u043E\u043B\u044C\u043A\u043E \u043F\u0440\u0438 \u0422\u0438\u043F: \u043E\u043F\u0446\u0438\u044F.",
  "\u0421\u043E\u0441\u0442\u0430\u0432:": "\u041C\u0430\u0441\u0441\u0438\u0432 pflow:\u041A\u043E\u043C\u043F\u043E\u043D\u0435\u043D\u0442 \u2014 \u043C\u043E\u0434\u0443\u043B\u0438, \u0438\u0437 \u043A\u043E\u0442\u043E\u0440\u044B\u0445 \u0441\u043E\u0431\u0440\u0430\u043D\u0430 \u0443\u0441\u043B\u0443\u0433\u0430. Cross-layer \u0441\u0441\u044B\u043B\u043A\u0430.",
  "\u041E\u043F\u043E\u0440\u044B:": "\u041E\u043F\u043E\u0440\u044B, \u043D\u0430 \u043A\u043E\u0442\u043E\u0440\u044B\u0445 \u0431\u0430\u0437\u0438\u0440\u0443\u0435\u0442\u0441\u044F \u0443\u0441\u043B\u0443\u0433\u0430/\u0441\u0446\u0435\u043D\u0430\u0440\u0438\u0439.",
  "\u0421\u0435\u0433\u043C\u0435\u043D\u0442\u044B:": "\u0421\u0435\u0433\u043C\u0435\u043D\u0442\u044B, \u043A\u043E\u0442\u043E\u0440\u044B\u043C \u0430\u0434\u0440\u0435\u0441\u043E\u0432\u0430\u043D\u0430 \u0443\u0441\u043B\u0443\u0433\u0430 (\u0441\u0432\u043E\u0431\u043E\u0434\u043D\u044B\u0435 \u0441\u0442\u0440\u043E\u043A\u0438 \u0438\u043B\u0438 \u0441\u0441\u044B\u043B\u043A\u0438 \u043D\u0430 pflow).",
  "\u0421\u0435\u0433\u043C\u0435\u043D\u0442:": "\u0421\u0441\u044B\u043B\u043A\u0430 \u043D\u0430 \u0421\u0435\u0433\u043C\u0435\u043D\u0442 \u0438\u0437 pflow \u0434\u043B\u044F \u043F\u0435\u0440\u0441\u043E\u043D\u044B.",
  "\u041F\u0435\u0440\u0441\u043E\u043D\u044B:": "\u0421\u043F\u0438\u0441\u043E\u043A \u043F\u0435\u0440\u0441\u043E\u043D (\u0434\u043B\u044F \u0443\u0441\u043B\u0443\u0433\u0438 \u0438\u043B\u0438 \u043A\u043E\u043D\u0442\u0435\u043A\u0441\u0442\u0430).",
  "\u041A\u043E\u043C\u0443:": "\u0421\u043F\u0438\u0441\u043E\u043A \u043F\u0435\u0440\u0441\u043E\u043D, \u043A\u043E\u0442\u043E\u0440\u044B\u043C \u0434\u0430\u0451\u0442\u0441\u044F \u044D\u0442\u043E \u043E\u0431\u0435\u0449\u0430\u043D\u0438\u0435.",
  "\u041F\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u0435\u0442:": "\u0421\u043F\u0438\u0441\u043E\u043A \u043E\u0431\u0435\u0449\u0430\u043D\u0438\u0439, \u043A\u043E\u0442\u043E\u0440\u044B\u0435 \u0441\u0446\u0435\u043D\u0430\u0440\u0438\u0439 \u0434\u0435\u043C\u043E\u043D\u0441\u0442\u0440\u0438\u0440\u0443\u0435\u0442 \u0432 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0438.",
  "\u041A\u043E\u043D\u0442\u0435\u043A\u0441\u0442\u044B:": "\u041A\u043E\u043D\u0442\u0435\u043A\u0441\u0442\u044B, \u0432 \u043A\u043E\u0442\u043E\u0440\u044B\u0445 \u043F\u0440\u0438\u043C\u0435\u043D\u044F\u0435\u0442\u0441\u044F \u0443\u0441\u043B\u0443\u0433\u0430.",
  "\u041E\u0431\u0435\u0449\u0430\u043D\u0438\u044F:": "\u0421\u043F\u0438\u0441\u043E\u043A \u043E\u0431\u0435\u0449\u0430\u043D\u0438\u0439 \u0443\u0441\u043B\u0443\u0433\u0438 (\u043F\u043B\u043E\u0441\u043A\u0438\u0439) \u0438\u043B\u0438 \u043E\u0431\u0435\u0449\u0430\u043D\u0438\u0439 \u043A\u043E\u043D\u0442\u0435\u043A\u0441\u0442\u0430 (\u0441 \u0443\u0440\u043E\u0432\u043D\u044F\u043C\u0438 \u043A\u043B\u044E\u0447\u0435\u0432\u043E\u0435/\u043F\u043E\u0434\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u044E\u0449\u0435\u0435).",
  "\u0424\u043E\u0440\u043C\u0443\u043B\u0438\u0440\u043E\u0432\u043A\u0430:": "\u041A\u043E\u043D\u043A\u0440\u0435\u0442\u043D\u043E\u0435 \u043E\u043F\u0438\u0441\u0430\u043D\u0438\u0435, \u0447\u0442\u043E \u0437\u043D\u0430\u0447\u0438\u0442 \u043E\u0431\u0435\u0449\u0430\u043D\u0438\u0435 \u0432\u044B\u043F\u043E\u043B\u043D\u0435\u043D\u043E.",
  "\u0421\u0438\u0442\u0443\u0430\u0446\u0438\u044F:": "\u0427\u0442\u043E \u0432\u043E\u043A\u0440\u0443\u0433 \u043F\u0440\u043E\u0438\u0441\u0445\u043E\u0434\u0438\u0442 \u0443 \u043A\u043B\u0438\u0435\u043D\u0442\u0430.",
  "\u042D\u043C\u043E\u0446\u0438\u044F:": "\u0427\u0442\u043E \u0447\u0443\u0432\u0441\u0442\u0432\u0443\u0435\u0442 \u043A\u043B\u0438\u0435\u043D\u0442.",
  "\u0422\u0440\u0438\u0433\u0433\u0435\u0440:": "\u041A\u043E\u043D\u043A\u0440\u0435\u0442\u043D\u044B\u0439 \u043C\u043E\u043C\u0435\u043D\u0442, \u043A\u043E\u0433\u0434\u0430 \u043A\u043B\u0438\u0435\u043D\u0442 \u0434\u0443\u043C\u0430\u0435\u0442 \xAB\u043D\u0430\u0434\u043E \u0447\u0442\u043E-\u0442\u043E \u0434\u0435\u043B\u0430\u0442\u044C\xBB.",
  "\u0427\u0442\u043E_\u0432\u0430\u0436\u043D\u043E:": "\u041F\u043E\u0442\u0440\u0435\u0431\u043D\u043E\u0441\u0442\u0438 \u043A\u043B\u0438\u0435\u043D\u0442\u0430 \u0432 \u044D\u0442\u043E\u0439 \u0441\u0438\u0442\u0443\u0430\u0446\u0438\u0438 (\u0432\u0445\u043E\u0434\u043D\u043E\u0439 \u0441\u0438\u0433\u043D\u0430\u043B).",
  "\u0427\u0442\u043E_\u043D\u0435_\u0432\u0430\u0436\u043D\u043E:": "\u0427\u0442\u043E \u0432 \u044D\u0442\u043E\u043C \u043A\u043E\u043D\u0442\u0435\u043A\u0441\u0442\u0435 \u043D\u0435 \u043A\u0440\u0438\u0442\u0438\u0447\u043D\u043E \u2014 \u043F\u043E\u043C\u043E\u0433\u0430\u0435\u0442 \u043D\u0435 \u043F\u0435\u0440\u0435\u0433\u0440\u0443\u0436\u0430\u0442\u044C \u0441\u043E\u043E\u0431\u0449\u0435\u043D\u0438\u0435.",
  "\u041A\u0430\u043D\u0430\u043B\u044B:": "\u041C\u0430\u0441\u0441\u0438\u0432 \u0441\u0441\u044B\u043B\u043E\u043A \u043D\u0430 pflow:\u041A\u0430\u043D\u0430\u043B \u2014 \u0433\u0434\u0435 \u043A\u043B\u0438\u0435\u043D\u0442 \u0432 \u044D\u0442\u043E\u043C \u043A\u043E\u043D\u0442\u0435\u043A\u0441\u0442\u0435 \u043D\u0430\u0445\u043E\u0434\u0438\u0442 \u0443\u0441\u043B\u0443\u0433\u0443. Cross-layer \u0441\u0441\u044B\u043B\u043A\u0438 \u043D\u0430 \u041A\u0430\u043D\u0430\u043B\u044B \u041A\u0430\u043D\u0432\u0430\u0441\u0430.",
  "\u0410\u043B\u044C\u0442\u0435\u0440\u043D\u0430\u0442\u0438\u0432\u044B:": "\u041C\u0430\u0441\u0441\u0438\u0432 \u0441\u0441\u044B\u043B\u043E\u043A \u043D\u0430 pflow:\u0410\u043B\u044C\u0442\u0435\u0440\u043D\u0430\u0442\u0438\u0432\u0430 \u2014 \u0447\u0442\u043E \u043A\u043B\u0438\u0435\u043D\u0442 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0435\u0442 \u0438\u043B\u0438 \u043C\u043E\u0433 \u0431\u044B \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u044C \u0432\u043C\u0435\u0441\u0442\u043E \u043D\u0430\u0448\u0435\u0433\u043E \u0440\u0435\u0448\u0435\u043D\u0438\u044F.",
  "\u0420\u043E\u043B\u044C_\u0432_\u0441\u0434\u0435\u043B\u043A\u0435:": "B2B-\u0440\u043E\u043B\u044C \u0432 \u0441\u0434\u0435\u043B\u043A\u0435: \u041B\u041F\u0420 (\u043F\u0440\u0438\u043D\u0438\u043C\u0430\u0435\u0442 \u0440\u0435\u0448\u0435\u043D\u0438\u0435) / \u041B\u0414\u0420 (\u0433\u043E\u0442\u043E\u0432\u0438\u0442 \u0440\u0435\u0448\u0435\u043D\u0438\u0435) / \u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u0435\u043B\u044C / \u0441\u043F\u043E\u043D\u0441\u043E\u0440 / \u0441\u043A\u0435\u043F\u0442\u0438\u043A. \u041E\u043F\u0446\u0438\u043E\u043D\u0430\u043B\u044C\u043D\u043E.",
  "\u0427\u0442\u043E_\u043F\u043E\u043A\u0443\u043F\u0430\u0435\u0442:": "\u0427\u0442\u043E \u043F\u0435\u0440\u0441\u043E\u043D\u0430 \u0438\u0449\u0435\u0442 \u0432 \u043F\u043E\u043A\u0443\u043F\u043A\u0435 (\u043A\u043E\u043D\u0442\u0440\u043E\u043B\u044C, \u0441\u043F\u043E\u043A\u043E\u0439\u0441\u0442\u0432\u0438\u0435, \u0441\u0442\u0430\u0442\u0443\u0441, \u0438\u043D\u0441\u0442\u0440\u0443\u043C\u0435\u043D\u0442). B2B-\u043F\u0430\u0440\u0430\u043C\u0435\u0442\u0440.",
  "\u0427\u0442\u043E_\u043E\u0434\u043E\u0431\u0440\u044F\u0435\u0442:": "\u0427\u0442\u043E \u0432 \u043F\u043E\u0434\u0445\u043E\u0434\u0435 \u043F\u0435\u0440\u0441\u043E\u043D\u0443 \u043F\u043E\u0434\u043A\u0443\u043F\u0430\u0435\u0442 (\u043F\u043E\u043D\u044F\u0442\u043D\u044B\u0435 \u0430\u0440\u0442\u0435\u0444\u0430\u043A\u0442\u044B, \u0438\u0437\u043C\u0435\u0440\u0438\u043C\u043E\u0441\u0442\u044C, \u0442\u0435\u0445\u043D\u043E\u043B\u043E\u0433\u0438\u0447\u043D\u043E\u0441\u0442\u044C). B2B-\u043F\u0430\u0440\u0430\u043C\u0435\u0442\u0440.",
  "\u0427\u0442\u043E_\u0431\u043B\u043E\u043A\u0438\u0440\u0443\u0435\u0442:": "\u0427\u0442\u043E \u0443 \u043F\u0435\u0440\u0441\u043E\u043D\u044B \u0432\u044B\u0437\u044B\u0432\u0430\u0435\u0442 \u043E\u0442\u0442\u043E\u0440\u0436\u0435\u043D\u0438\u0435 (\u0440\u0438\u0442\u043E\u0440\u0438\u043A\u0430 \u0431\u0435\u0437 \u0430\u0440\u0442\u0435\u0444\u0430\u043A\u0442\u043E\u0432, \u043D\u0435\u043A\u043E\u043D\u043A\u0440\u0435\u0442\u043D\u044B\u0435 \u043E\u0431\u0435\u0449\u0430\u043D\u0438\u044F). B2B-\u043F\u0430\u0440\u0430\u043C\u0435\u0442\u0440.",
  "\u041F\u0440\u0438\u043E\u0440\u0438\u0442\u0435\u0442:": "\u041F\u0440\u0438\u043E\u0440\u0438\u0442\u0435\u0442 \u041A\u043E\u043D\u0442\u0435\u043A\u0441\u0442\u0430 \u043F\u0440\u0438 \u0440\u0430\u043D\u0436\u0438\u0440\u043E\u0432\u0430\u043D\u0438\u0438 (\u043D\u0438\u0437\u043A\u0438\u0439/\u0441\u0440\u0435\u0434\u043D\u0438\u0439/\u0432\u044B\u0441\u043E\u043A\u0438\u0439/\u043A\u0440\u0438\u0442\u0438\u0447\u0435\u0441\u043A\u0438\u0439). \u0418\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0435\u0442\u0441\u044F \u0434\u043B\u044F \u0444\u043E\u043A\u0443\u0441\u0430 \u0440\u0430\u0437\u0440\u0430\u0431\u043E\u0442\u043A\u0438 \u0438 \u043C\u0430\u0440\u043A\u0435\u0442\u0438\u043D\u0433\u043E\u0432\u044B\u0445 \u043C\u0430\u0442\u0435\u0440\u0438\u0430\u043B\u043E\u0432.",
  "\u0421\u0438\u043B\u0430:": '\u0421\u0438\u043B\u0430 \u0441\u0438\u0433\u043D\u0430\u043B\u0430 \u0440\u044B\u043D\u043A\u0430: \u043D\u0438\u0437\u043A\u0430\u044F / \u0441\u0440\u0435\u0434\u043D\u044F\u044F / \u0432\u044B\u0441\u043E\u043A\u0430\u044F. \u041D\u0430\u0441\u043A\u043E\u043B\u044C\u043A\u043E \u0440\u0435\u0430\u043B\u0435\u043D \u0441\u043F\u0440\u043E\u0441 \u0432 \u044D\u0442\u043E\u043C \u043A\u043E\u043D\u0442\u0435\u043A\u0441\u0442\u0435 \u2014 \u0447\u0430\u0441\u0442\u043E\u0442\u0430 \u0432\u043E\u0437\u043D\u0438\u043A\u043D\u043E\u0432\u0435\u043D\u0438\u044F, \u043E\u0441\u0442\u0440\u043E\u0442\u0430, \u0433\u043E\u0442\u043E\u0432\u043D\u043E\u0441\u0442\u044C \u043F\u043B\u0430\u0442\u0438\u0442\u044C. \u041E\u0440\u0442\u043E\u0433\u043E\u043D\u0430\u043B\u044C\u043D\u0430 \u041F\u0440\u0438\u043E\u0440\u0438\u0442\u0435\u0442\u0443 (\u041F\u0440\u0438\u043E\u0440\u0438\u0442\u0435\u0442 \u2014 \u043A\u0443\u0434\u0430 \u0438\u043D\u0432\u0435\u0441\u0442\u0438\u0440\u0443\u0435\u043C \u043C\u044B; \u0421\u0438\u043B\u0430 \u2014 \u0447\u0442\u043E \u043D\u0430\u0431\u043B\u044E\u0434\u0430\u0435\u043C \u0443 \u0440\u044B\u043D\u043A\u0430). \u0414\u0435\u0439\u0441\u0442\u0432\u0443\u044E\u0449\u0430\u044F \u0423\u0441\u043B\u0443\u0433\u0430 \u043D\u0430 \u043D\u0438\u0437\u043A\u043E\u0439 \u0421\u0438\u043B\u0435 \u043F\u043E\u043F\u0430\u0434\u0430\u0435\u0442 \u0432 "\u041F\u0440\u043E\u0442\u0438\u0432\u043E\u0440\u0435\u0447\u0438\u0435 \u0441\u0442\u0430\u0442\u0443\u0441\u043E\u0432".',
  "\u0417\u0430\u043A\u0440\u044B\u0432\u0430\u0435\u0442:": "\u041C\u0430\u0441\u0441\u0438\u0432 \u0441\u0441\u044B\u043B\u043E\u043A \u043D\u0430 pflow:\u0420\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442 (ODI Outcome) \u2014 \u043A\u0430\u043A\u0438\u0435 \u0438\u0441\u0445\u043E\u0434\u044B \u0437\u0430\u043A\u0440\u044B\u0432\u0430\u0435\u0442 \u044D\u0442\u043E \u043E\u0431\u0435\u0449\u0430\u043D\u0438\u0435. \u041D\u0430 \u0441\u0442\u043E\u0440\u043E\u043D\u0435 Outcome reverse-inlay \u{1F91D} \u043F\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u0435\u0442 \u0432\u0441\u0435 \u0441\u0441\u044B\u043B\u0430\u044E\u0449\u0438\u0435\u0441\u044F \u043E\u0431\u0435\u0449\u0430\u043D\u0438\u044F.",
  "\u0418\u043D\u0432\u0430\u0440\u0438\u0430\u043D\u0442:": "\u041C\u0430\u0441\u0441\u0438\u0432 \u0441\u0441\u044B\u043B\u043E\u043A \u043D\u0430 pflow:\u0420\u0435\u0441\u0443\u0440\u0441 \u2014 \u043D\u0430 \u043A\u0430\u043A\u0438\u0445 \u0440\u0435\u0441\u0443\u0440\u0441\u0430\u0445 \u0441\u0442\u0440\u043E\u0438\u0442\u0441\u044F \u0432\u044B\u043F\u043E\u043B\u043D\u0438\u043C\u043E\u0441\u0442\u044C \u043E\u0431\u0435\u0449\u0430\u043D\u0438\u044F. \u041D\u0435 \u043F\u0443\u0442\u0430\u0442\u044C \u0441 `\u041E\u043F\u043E\u0440\u0430.\u041E\u0431\u0435\u0441\u043F\u0435\u0447\u0438\u0432\u0430\u0435\u0442:` (\u0442\u0430\u043C \u0420\u0435\u0441\u0443\u0440\u0441 \u043E\u0431\u0435\u0441\u043F\u0435\u0447\u0438\u0432\u0430\u0435\u0442 \u041E\u043F\u043E\u0440\u0443).",
  "\u041F\u0440\u043E\u0434\u0443\u043A\u0442:": "\u041F\u0440\u043E\u0434\u0443\u043A\u0442 \u2014 \u0443\u043F\u0430\u043A\u043E\u0432\u043A\u0430 \u043D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u0438\u0445 \u0423\u0441\u043B\u0443\u0433 \u043F\u043E\u0434 \u043E\u0434\u043D\u0438\u043C \u0431\u0440\u0435\u043D\u0434\u043E\u043C (\u0430\u043D\u0430\u043B\u043E\u0433 pflow:\u041A\u0430\u043D\u0432\u0430\u0441 \u043D\u0430 \u043E\u043F\u0435\u0440\u0430\u0446\u0438\u043E\u043D\u043D\u043E\u043C \u0441\u043B\u043E\u0435). \u0412 \u043A\u043E\u043D\u0442\u0435\u043A\u0441\u0442\u0435 \u0422\u0440\u0435\u043A\u0430 \u2014 \u0441\u0441\u044B\u043B\u043A\u0430 \u043D\u0430 \u043A\u043E\u043D\u043A\u0440\u0435\u0442\u043D\u044B\u0439 \u041F\u0440\u043E\u0434\u0443\u043A\u0442.",
  "\u0422\u0440\u0435\u043A:": "\u0422\u0440\u0435\u043A \u2014 \u043C\u0430\u0440\u0448\u0440\u0443\u0442 \u0421\u0435\u0433\u043C\u0435\u043D\u0442\u0430 \u0447\u0435\u0440\u0435\u0437 \u041F\u0440\u043E\u0434\u0443\u043A\u0442. \u042D\u0442\u0430\u043F\u044B (\u0443\u043F\u043E\u0440\u044F\u0434\u043E\u0447\u0435\u043D\u043D\u044B\u0439 \u0441\u043F\u0438\u0441\u043E\u043A \u0423\u0441\u043B\u0443\u0433) + \u0410\u043F\u0433\u0440\u0435\u0439\u0434\u044B (\u0441\u0441\u044B\u043B\u043A\u0438 \u043D\u0430 \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0443\u044E\u0449\u0438\u0435 \u0410\u043F\u0433\u0440\u0435\u0439\u0434:).",
  "\u041F\u043E\u0440\u0442\u0444\u0435\u043B\u044C:": "\u041F\u043E\u0440\u0442\u0444\u0435\u043B\u044C \u2014 \u0438\u0435\u0440\u0430\u0440\u0445\u0438\u044F \u041F\u0440\u043E\u0434\u0443\u043A\u0442\u043E\u0432 \u0438 \u0422\u0440\u0435\u043A\u043E\u0432 \u043E\u0434\u043D\u043E\u0439 \u043A\u043E\u043C\u0430\u043D\u0434\u043D\u043E\u0439 \u0435\u0434\u0438\u043D\u0438\u0446\u044B (\u0430\u043D\u0430\u043B\u043E\u0433 pflow:\u042E\u043D\u0438\u0442).",
  "\u041A\u0430\u043D\u0432\u0430\u0441:": "\u0421\u0441\u044B\u043B\u043A\u0430 \u043D\u0430 pflow:\u041A\u0430\u043D\u0432\u0430\u0441. \u0412 \u041F\u0440\u043E\u0434\u0443\u043A\u0442\u0435 \u2014 \u043A\u0430\u043A\u043E\u0439 \u041A\u0430\u043D\u0432\u0430\u0441 \u044D\u0442\u043E\u0442 \u041F\u0440\u043E\u0434\u0443\u043A\u0442 \u043E\u043F\u0435\u0440\u0430\u0446\u0438\u043E\u043D\u0430\u043B\u0438\u0437\u0438\u0440\u0443\u0435\u0442.",
  "\u042E\u043D\u0438\u0442:": "\u0421\u0441\u044B\u043B\u043A\u0430 \u043D\u0430 pflow:\u042E\u043D\u0438\u0442. \u0412 \u041F\u043E\u0440\u0442\u0444\u0435\u043B\u0435 \u2014 \u043A\u0430\u043A\u0443\u044E \u043A\u043E\u043C\u0430\u043D\u0434\u043D\u0443\u044E \u0435\u0434\u0438\u043D\u0438\u0446\u0443 \u044D\u0442\u043E\u0442 \u041F\u043E\u0440\u0442\u0444\u0435\u043B\u044C \u043E\u0442\u0440\u0430\u0436\u0430\u0435\u0442.",
  "\u041E\u0441\u043D\u043E\u0432\u043D\u0430\u044F:": "\u041E\u0441\u043D\u043E\u0432\u043D\u0430\u044F \u0423\u0441\u043B\u0443\u0433\u0430 \u041F\u0440\u043E\u0434\u0443\u043A\u0442\u0430 \u2014 \u0442\u043E\u0447\u043A\u0430 \u0432\u0445\u043E\u0434\u0430 \u0441\u0435\u0433\u043C\u0435\u043D\u0442\u0430. \u041E\u0434\u0438\u043D\u043E\u0447\u043D\u0430\u044F \u0441\u0441\u044B\u043B\u043A\u0430 \u043D\u0430 Service.",
  "\u0423\u0440\u043E\u0432\u043D\u0438:": "Tier-\u0443\u0441\u043B\u0443\u0433\u0438 \u041F\u0440\u043E\u0434\u0443\u043A\u0442\u0430: \u0440\u0430\u0437\u043D\u044B\u0435 \u0443\u0440\u043E\u0432\u043D\u0438 \u0437\u0440\u0435\u043B\u043E\u0441\u0442\u0438/\u0433\u043B\u0443\u0431\u0438\u043D\u044B (Basic/Pro/Enterprise). \u041C\u0430\u0441\u0441\u0438\u0432 \u0441\u0441\u044B\u043B\u043E\u043A \u043D\u0430 Service.",
  "\u041E\u043F\u0446\u0438\u0438:": "\u041E\u043F\u0446\u0438\u043E\u043D\u0430\u043B\u044C\u043D\u044B\u0435 \u0423\u0441\u043B\u0443\u0433\u0438 \u041F\u0440\u043E\u0434\u0443\u043A\u0442\u0430 (add-on-\u044B, \u043F\u0440\u0438\u0446\u0435\u043F\u043B\u044F\u044E\u0449\u0438\u0435\u0441\u044F \u043A \u041E\u0441\u043D\u043E\u0432\u043D\u043E\u0439). \u041C\u0430\u0441\u0441\u0438\u0432 \u0441\u0441\u044B\u043B\u043E\u043A \u043D\u0430 Service.",
  "\u042D\u0442\u0430\u043F\u044B:": "\u0423\u043F\u043E\u0440\u044F\u0434\u043E\u0447\u0435\u043D\u043D\u0430\u044F \u043F\u043E\u0441\u043B\u0435\u0434\u043E\u0432\u0430\u0442\u0435\u043B\u044C\u043D\u043E\u0441\u0442\u044C \u0423\u0441\u043B\u0443\u0433 \u0432 \u0422\u0440\u0435\u043A\u0435. \u041A\u0430\u0436\u0434\u044B\u0439 \u044D\u0442\u0430\u043F \u2014 \u0441\u0441\u044B\u043B\u043A\u0430 \u043D\u0430 Service. \u041F\u0435\u0440\u0435\u0445\u043E\u0434\u044B \u043C\u0435\u0436\u0434\u0443 \u044D\u0442\u0430\u043F\u0430\u043C\u0438 \u043E\u043F\u0438\u0441\u044B\u0432\u0430\u044E\u0442\u0441\u044F \u0447\u0435\u0440\u0435\u0437 \u0410\u043F\u0433\u0440\u0435\u0439\u0434\u044B:.",
  "\u0410\u043F\u0433\u0440\u0435\u0439\u0434\u044B:": "\u0412 \u0422\u0440\u0435\u043A\u0435 \u2014 \u043C\u0430\u0441\u0441\u0438\u0432 \u0441\u0441\u044B\u043B\u043E\u043A \u043D\u0430 \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0443\u044E\u0449\u0438\u0435 `\u0410\u043F\u0433\u0440\u0435\u0439\u0434:` (\u043F\u043E\u043F\u0430\u0440\u043D\u044B\u0435 \u043F\u0435\u0440\u0435\u0445\u043E\u0434\u044B \u0418\u0437\u2192\u0412 \u0441 \u0443\u0441\u043B\u043E\u0432\u0438\u0435\u043C). \u0412\u0430\u043B\u0438\u0434\u0430\u0442\u043E\u0440 \u0442\u0440\u0435\u0431\u0443\u0435\u0442, \u0447\u0442\u043E\u0431\u044B \u0410\u043F\u0433\u0440\u0435\u0439\u0434.\u0418\u0437/\u0412 \u043B\u0435\u0436\u0430\u043B\u0438 \u0432 \u042D\u0442\u0430\u043F\u044B:.",
  "\u041F\u0440\u043E\u0434\u0443\u043A\u0442\u044B:": "\u041F\u0440\u043E\u0434\u0443\u043A\u0442\u044B \u041F\u043E\u0440\u0442\u0444\u0435\u043B\u044F. \u041C\u0430\u0441\u0441\u0438\u0432 \u0441\u0441\u044B\u043B\u043E\u043A \u043D\u0430 SvcProduct.",
  "\u0422\u0440\u0435\u043A\u0438:": "\u0422\u0440\u0435\u043A\u0438 \u041F\u043E\u0440\u0442\u0444\u0435\u043B\u044F. \u041C\u0430\u0441\u0441\u0438\u0432 \u0441\u0441\u044B\u043B\u043E\u043A \u043D\u0430 SvcTrack."
};
