var SolutionValidator = class {
  checkHasApproach(solution, accept) {
    const ok = solution.items.some((i) => i.$type === "VPCSolutionApproach");
    if (!ok) accept("warning", "\u043D\u0435\u0442 \u041F\u043E\u0434\u0445\u043E\u0434:", {
      node: solution,
      property: "name",
      code: "pflow.missing-required",
      data: {
        why: "\u0411\u0435\u0437 \u041F\u043E\u0434\u0445\u043E\u0434: \u043D\u0435\u043F\u043E\u043D\u044F\u0442\u043D\u043E, \u043A\u0430\u043A \u041F\u0440\u0435\u0434\u043B\u043E\u0436\u0435\u043D\u0438\u0435 \u0440\u0430\u0431\u043E\u0442\u0430\u0435\u0442.",
        fix: { kind: "add-field", title: "\u0414\u043E\u0431\u0430\u0432\u0438\u0442\u044C \u041F\u043E\u0434\u0445\u043E\u0434:", snippet: '\u041F\u043E\u0434\u0445\u043E\u0434: "\u043A\u0430\u043A \u0438\u043C\u0435\u043D\u043D\u043E \u0440\u0430\u0431\u043E\u0442\u0430\u0435\u0442"' }
      }
    });
  }
  checkHasStatus(solution, accept) {
    const ok = solution.items.some((i) => i.$type === "VPCSolutionStatus");
    if (!ok) accept("warning", "\u043D\u0435\u0442 \u0421\u0442\u0430\u0442\u0443\u0441:", {
      node: solution,
      property: "name",
      code: "pflow.missing-required",
      data: {
        why: "\u0411\u0435\u0437 \u0421\u0442\u0430\u0442\u0443\u0441: \u043D\u0435 \u043F\u043E\u043D\u044F\u0442\u043D\u0430 \u0437\u0440\u0435\u043B\u043E\u0441\u0442\u044C \u041F\u0440\u0435\u0434\u043B\u043E\u0436\u0435\u043D\u0438\u044F.",
        fix: { kind: "add-field", title: "\u0414\u043E\u0431\u0430\u0432\u0438\u0442\u044C \u0421\u0442\u0430\u0442\u0443\u0441: \u0438\u0434\u0435\u044F", snippet: "\u0421\u0442\u0430\u0442\u0443\u0441: \u0438\u0434\u0435\u044F" }
      }
    });
  }
  /** Предложение «работает» без подтверждающего top-level Сигнала, чьи пути ведут к этому Предложению. */
  checkWorkingWithoutSignal(solution, accept) {
    const statusField = solution.items.find((i) => i.$type === "VPCSolutionStatus");
    if (!statusField) return;
    const status = statusField.value;
    if (status !== "\u0440\u0430\u0431\u043E\u0442\u0430\u0435\u0442") return;
    const doc = ast_utils_exports.getDocument(solution);
    const root2 = doc?.parseResult?.value;
    if (!root2?.elements) return;
    for (const el of root2.elements) {
      if (el.$type !== "Signal") continue;
      const signal = el;
      const confirms = signal.fields.find((f) => f.$type === "SignalConfirms");
      if (!confirms) continue;
      for (const path of confirms.paths) {
        const pathRef = path;
        if (!pathRef.root?.target?.ref) continue;
        const target = resolvePathRef(pathRef, FIELD_TYPE_TO_DSL_NAME);
        if (target === solution) return;
      }
    }
    accept("warning", "\u0421\u0442\u0430\u0442\u0443\u0441: \xAB\u0440\u0430\u0431\u043E\u0442\u0430\u0435\u0442\xBB \u0431\u0435\u0437 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u044E\u0449\u0435\u0433\u043E \u0421\u0438\u0433\u043D\u0430\u043B\u0430", {
      node: solution,
      property: "name",
      code: "pflow.solution.unproven",
      data: {
        why: "\u0421\u0442\u0430\u0442\u0443\u0441 \xAB\u0440\u0430\u0431\u043E\u0442\u0430\u0435\u0442\xBB \u043D\u0435\u043E\u0431\u043E\u0441\u043D\u043E\u0432\u0430\u043D \u0431\u0435\u0437 \u0434\u043E\u043A\u0430\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u043E\u0439 \u0431\u0430\u0437\u044B.",
        fix: { title: `\u0414\u043E\u0431\u0430\u0432\u044C top-level \u0421\u0438\u0433\u043D\u0430\u043B \u0441 \u041F\u043E\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u0435\u0442: VPC."<\u0438\u043C\u044F>"/\u041F\u0440\u0435\u0434\u043B\u043E\u0436\u0435\u043D\u0438\u0435."${solution.name}".` }
      }
    });
  }
  checkSolvesJob(solution, accept) {
    const ok = solution.items.some((i) => i.$type === "VPCSolvesJob");
    if (!ok) accept("warning", "\u043D\u0435\u0442 \u0420\u0435\u0448\u0430\u0435\u0442:", {
      node: solution,
      property: "name",
      code: "pflow.missing-required",
      data: {
        why: "\u041F\u0440\u0435\u0434\u043B\u043E\u0436\u0435\u043D\u0438\u0435 \u0434\u043E\u043B\u0436\u043D\u043E \u0437\u0430\u043A\u0440\u044B\u0432\u0430\u0442\u044C \u043A\u043E\u043D\u043A\u0440\u0435\u0442\u043D\u0443\u044E JTBD.",
        fix: { kind: "add-field", title: "\u0414\u043E\u0431\u0430\u0432\u0438\u0442\u044C \u0420\u0435\u0448\u0430\u0435\u0442:", snippet: '\u0420\u0435\u0448\u0430\u0435\u0442: "\u0438\u043C\u044F_\u0440\u0430\u0431\u043E\u0442\u044B"' }
      }
    });
  }
};

