// ../../src/language/validators/segment-validator.ts
var SegmentValidator = class {
  constructor(services) {
    this.services = services;
  }
  checkHasDescription(segment, accept) {
    const ok = segment.items.some((i) => isOfType(i, "SegmentDescription"));
    if (!ok) accept("warning", "\u043D\u0435\u0442 \u041E\u043F\u0438\u0441\u0430\u043D\u0438\u0435:", {
      node: segment,
      property: "name",
      code: "pflow.missing-required",
      data: {
        why: "\u0411\u0435\u0437 \u041E\u043F\u0438\u0441\u0430\u043D\u0438\u0435: \u043D\u0435\u043F\u043E\u043D\u044F\u0442\u043D\u043E, \u0447\u044C\u044E JTBD \u0437\u0430\u043A\u0440\u044B\u0432\u0430\u0435\u043C.",
        fix: { kind: "add-field", title: "\u0414\u043E\u0431\u0430\u0432\u0438\u0442\u044C \u041E\u043F\u0438\u0441\u0430\u043D\u0438\u0435:", snippet: '\u041E\u043F\u0438\u0441\u0430\u043D\u0438\u0435: "\u043A\u043E\u0440\u043E\u0442\u043A\u043E, \u043A\u0442\u043E \u044D\u0442\u0438 \u043B\u044E\u0434\u0438"' }
      }
    });
  }
  // Сегмент существует, но ни один VPC в воркспейсе на него не ссылается.
  // «Мёртвая аудитория»: гипотеза не превращена в продукт.
  // Теперь Сегмент привязывается к VPC через VPCSegment, а не к Canvas напрямую.
  checkReferencedByAnyCanvas(segment, accept) {
    const docs = this.services.shared.workspace.LangiumDocuments;
    for (const doc of docs.all) {
      const model = doc.parseResult?.value;
      if (!model?.elements) continue;
      for (const vpc of filterByType(model.elements, "VPC")) {
        for (const vi of vpc.items) {
          if (vi.$type !== "VPCSegment") continue;
          const refName = vi.segment?.ref?.name;
          if (refName === segment.name) return;
        }
      }
    }
    accept("warning", "\u043D\u0435 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0435\u0442\u0441\u044F \u043D\u0438 \u043E\u0434\u043D\u0438\u043C \u041A\u0430\u043D\u0432\u0430\u0441\u043E\u043C", {
      node: segment,
      property: "name",
      code: "pflow.orphan",
      data: {
        why: "\u041C\u0451\u0440\u0442\u0432\u0430\u044F \u0430\u0443\u0434\u0438\u0442\u043E\u0440\u0438\u044F \u2014 \u0433\u0438\u043F\u043E\u0442\u0435\u0437\u0430 \u043D\u0435 \u043F\u0440\u0435\u0432\u0440\u0430\u0449\u0435\u043D\u0430 \u0432 \u043F\u0440\u043E\u0434\u0443\u043A\u0442.",
        fix: { title: `\u0414\u043E\u0431\u0430\u0432\u044C \u0421\u0435\u0433\u043C\u0435\u043D\u0442: "${segment.name}" \u0432 VPC \u0447\u0435\u0440\u0435\u0437 VPCSegment \u0438\u043B\u0438 \u0443\u0434\u0430\u043B\u0438 \u0421\u0435\u0433\u043C\u0435\u043D\u0442.` }
      }
    });
  }
};

